static class ModernChrome {
 [DllImport("user32.dll")]static extern bool ReleaseCapture();
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr hwnd,int msg,IntPtr wparam,IntPtr lparam);
 [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr hwnd,int attr,ref int value,int size);
 public static void Drag(WF.Form form){ReleaseCapture();SendMessage(form.Handle,0xA1,new IntPtr(2),IntPtr.Zero);}
 public static void Round(WF.Form form){try{int value=2;DwmSetWindowAttribute(form.Handle,33,ref value,4);}catch{}}
 public static UserControl Load(string resource){using(var stream=typeof(ModernChrome).Assembly.GetManifestResourceStream(resource)){if(stream==null)throw new Exception("Missing interface resource: "+resource);return (UserControl)XamlReader.Load(stream);}}
 public static ElementHost Host(UserControl content){return new ElementHost{Dock=WF.DockStyle.Fill,Child=content,BackColor=System.Drawing.Color.White};}
 public static void WireFrame(UserControl root,WF.Form form){((WpfButton)root.FindName("Min")).Click+=(s,e)=>form.WindowState=WF.FormWindowState.Minimized;((WpfButton)root.FindName("Close")).Click+=(s,e)=>form.Close();((Grid)root.FindName("TitleBar")).MouseLeftButtonDown+=(s,e)=>{DependencyObject node=e.OriginalSource as DependencyObject;while(node!=null){if(node is WpfButton)return;node=node is Visual?VisualTreeHelper.GetParent(node):LogicalTreeHelper.GetParent(node);}Drag(form);};}
}
class ModernMainView {
 public UserControl Root;WF.Form owner;WpfBox[] recorders=new WpfBox[Mode.All.Length];WpfButton[] runs=new WpfButton[Mode.All.Length];WpfButton save;bool filling;
 public Action<int> Run,ResetShortcut;public Action Save,Restore,BrowseShots,StartShot,StartRecord;public Action<bool> StartupChanged;public Action<int,uint,uint> ShortcutChanged;public Action<string,string,string,string,bool> FieldsChanged;
 public ModernMainView(WF.Form form,Settings config){owner=form;Root=ModernChrome.Load("ModernMain");ModernChrome.WireFrame(Root,form);for(int i=0;i<Mode.All.Length;i++){int index=i;recorders[i]=(WpfBox)Root.FindName("Key"+i);recorders[i].PreviewKeyDown+=(s,e)=>Record(index,e);runs[i]=(WpfButton)Root.FindName("Run"+i);runs[i].Click+=(s,e)=>{if(Run!=null)Run(index);};}save=(WpfButton)Root.FindName("Save");save.Click+=(s,e)=>{if(Save!=null)Save();};((WpfButton)Root.FindName("Restore")).Click+=(s,e)=>{if(Restore!=null)Restore();};((WpfButton)Root.FindName("ToolsNav")).Click+=(s,e)=>Page(0);((WpfButton)Root.FindName("ConnectionNav")).Click+=(s,e)=>Page(1);((WpfButton)Root.FindName("PreferencesNav")).Click+=(s,e)=>Page(2);
 ((WpfBox)Root.FindName("ApiUrl")).TextChanged+=(s,e)=>SyncFields();((WpfBox)Root.FindName("ModelName")).TextChanged+=(s,e)=>SyncFields();((PasswordBox)Root.FindName("ApiKey")).PasswordChanged+=(s,e)=>SyncFields();var language=(ComboBox)Root.FindName("TargetLanguage");foreach(string value in new[]{"简体中文","繁體中文","English","日本語","한국어","Français","Deutsch"})language.Items.Add(value);language.AddHandler(WpfBox.TextChangedEvent,new TextChangedEventHandler((s,e)=>SyncFields()));language.SelectionChanged+=(s,e)=>SyncFields();((CheckBox)Root.FindName("CompletionSound")).Checked+=(s,e)=>SyncFields();((CheckBox)Root.FindName("CompletionSound")).Unchecked+=(s,e)=>SyncFields();((CheckBox)Root.FindName("AutoStart")).Checked+=(s,e)=>{if(!filling&&StartupChanged!=null)StartupChanged(true);};((CheckBox)Root.FindName("AutoStart")).Unchecked+=(s,e)=>{if(!filling&&StartupChanged!=null)StartupChanged(false);};((WpfButton)Root.FindName("MailNav")).Click+=(s,e)=>Page(3);((WpfButton)Root.FindName("MailQQ")).Click+=(s,e)=>MailPreset("smtp.qq.com");((WpfButton)Root.FindName("Mail163")).Click+=(s,e)=>MailPreset("smtp.163.com");((WpfButton)Root.FindName("ShotsNav")).Click+=(s,e)=>Page(4);((WpfButton)Root.FindName("BrowseShotDirectory")).Click+=(s,e)=>{using(var picker=new WF.FolderBrowserDialog{SelectedPath=ReadShotDirectory(),Description="选择截图保存目录"})if(picker.ShowDialog(owner)==WF.DialogResult.OK)((WpfBox)Root.FindName("ShotDirectory")).Text=picker.SelectedPath;};((WpfButton)Root.FindName("OpenShotHistory")).Click+=(s,e)=>{if(BrowseShots!=null)BrowseShots();};((WpfButton)Root.FindName("StartShot")).Click+=(s,e)=>{if(StartShot!=null)StartShot();};((WpfButton)Root.FindName("StartRecord")).Click+=(s,e)=>{if(StartRecord!=null)StartRecord();};Fill(config);
 }
 public void UpdateShotHelp(Shortcut[] shortcuts){((TextBlock)Root.FindName("ShotShortcutHint")).Text="按 "+HotkeyInput.Format(shortcuts[8].Modifiers,shortcuts[8].Code)+" 开始截图，拖动框选区域；Esc 取消。";((TextBlock)Root.FindName("RecordingShortcutHint")).Text="按 "+HotkeyInput.Format(shortcuts[9].Modifiers,shortcuts[9].Code)+" 或点击工具栏摄像机按钮，选择全屏／区域及声音。\nCtrl+Alt+F9 暂停／继续 · Ctrl+Alt+F10 停止并保存 MP4";}
 public string ReadShotDirectory(){return ((WpfBox)Root.FindName("ShotDirectory")).Text;}
 public void Fill(Settings settings){UpdateShotHelp(settings.Shortcuts);((WpfBox)Root.FindName("ShotDirectory")).Text=settings.ScreenshotDirectory;FillMail(settings.Mail);filling=true;((CheckBox)Root.FindName("AutoStart")).IsChecked=StartupRegistration.IsEnabled();((WpfBox)Root.FindName("ApiUrl")).Text=settings.Url;((WpfBox)Root.FindName("ModelName")).Text=settings.Model;((PasswordBox)Root.FindName("ApiKey")).Password=settings.Key();((ComboBox)Root.FindName("TargetLanguage")).Text=settings.Language;((CheckBox)Root.FindName("CompletionSound")).IsChecked=settings.CompletionSound;((TextBlock)Root.FindName("CurrentModel")).Text=settings.Model;for(int i=0;i<Mode.All.Length;i++)SetShortcut(i,settings.Shortcuts[i].Modifiers,settings.Shortcuts[i].Code);filling=false;}
 void SyncFields(){if(filling)return;string model=((WpfBox)Root.FindName("ModelName")).Text;((TextBlock)Root.FindName("CurrentModel")).Text=model;if(FieldsChanged!=null)FieldsChanged(((WpfBox)Root.FindName("ApiUrl")).Text,model,((PasswordBox)Root.FindName("ApiKey")).Password,((ComboBox)Root.FindName("TargetLanguage")).Text,((CheckBox)Root.FindName("CompletionSound")).IsChecked==true);}
 void MailPreset(string host){((WpfBox)Root.FindName("MailHost")).Text=host;((WpfBox)Root.FindName("MailPort")).Text="465";((ComboBox)Root.FindName("MailSecurity")).SelectedIndex=0;}
 void FillMail(MailSettings c){((WpfBox)Root.FindName("MailHost")).Text=c.Host;((WpfBox)Root.FindName("MailPort")).Text=c.Port.ToString();((WpfBox)Root.FindName("MailFrom")).Text=c.From;((PasswordBox)Root.FindName("MailPassword")).Password=c.Password();((WpfBox)Root.FindName("MailContacts")).Text=c.Contacts;((WpfBox)Root.FindName("MailSubject")).Text=c.Subject;((ComboBox)Root.FindName("MailSecurity")).SelectedIndex=c.StartTls?1:0;}
 public MailSettings ReadMail(){int port;if(!int.TryParse(((WpfBox)Root.FindName("MailPort")).Text,out port))throw new Exception("SMTP 端口必须是数字");var c=new MailSettings{Host=((WpfBox)Root.FindName("MailHost")).Text.Trim(),Port=port,From=((WpfBox)Root.FindName("MailFrom")).Text.Trim(),Contacts=((WpfBox)Root.FindName("MailContacts")).Text,Subject=((WpfBox)Root.FindName("MailSubject")).Text,StartTls=((ComboBox)Root.FindName("MailSecurity")).SelectedIndex==1};c.SetPassword(((PasswordBox)Root.FindName("MailPassword")).Password);return c;}
 public int FocusedRecorder(){for(int i=0;i<Mode.All.Length;i++)if(recorders[i].IsKeyboardFocusWithin)return i;return -1;}
 public void SetShortcut(int index,uint modifiers,uint code){recorders[index].Text=HotkeyInput.Format(modifiers,code);recorders[index].Select(0,0);}
 void Record(int index,KeyEventArgs e){Key code=e.Key==Key.System?e.SystemKey:e.Key;if(code==Key.Tab)return;if(code==Key.Escape){if(ResetShortcut!=null)ResetShortcut(index);Keyboard.ClearFocus();e.Handled=true;return;}e.Handled=true;if(code==Key.LeftAlt||code==Key.RightAlt||code==Key.LeftCtrl||code==Key.RightCtrl||code==Key.LeftShift||code==Key.RightShift||code==Key.LWin||code==Key.RWin)return;uint modifiers=0;if((Keyboard.Modifiers&ModifierKeys.Alt)!=0)modifiers|=1;if((Keyboard.Modifiers&ModifierKeys.Control)!=0)modifiers|=2;if((Keyboard.Modifiers&ModifierKeys.Shift)!=0)modifiers|=4;if((modifiers&3)==0&&index!=8&&index!=9){recorders[index].Text="请加 Ctrl / Alt";return;}uint key=(uint)KeyInterop.VirtualKeyFromKey(code);SetShortcut(index,modifiers,key);if(ShortcutChanged!=null)ShortcutChanged(index,modifiers,key);}
 public void Status(string text){((TextBlock)Root.FindName("StatusText")).Text=text;}
 public void Busy(bool value){foreach(var button in runs)button.IsEnabled=!value;save.IsEnabled=!value;}
 public void Page(int page){string[] names={"Tools","Connection","Preferences","Mail","Shots"};for(int i=0;i<5;i++){((FrameworkElement)Root.FindName(names[i]+"Page")).Visibility=i==page?Visibility.Visible:Visibility.Collapsed;var button=(WpfButton)Root.FindName(names[i]+"Nav");button.Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(i==page?"#E8EDF9":"#F7F7F8"));button.Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(i==page?"#002FA7":"#19212B"));}((TextBlock)Root.FindName("PageTitle")).Text=new[]{"截图工具","模型连接","偏好设置","邮件发送","截图与贴图"}[page];((TextBlock)Root.FindName("PageDescription")).Text=new[]{"截图、识别和录屏，快捷键随时调用。","配置你使用的视觉模型服务。","调整翻译语言与完成提示。","Alt + 7 全屏截图，直接发送给以下联系人。","截图、标注与悬浮，历史保存在本地。"}[page];}
}
class ModernResultView {
 public UserControl Root;Mode mode;WpfBox output;DataGrid table;TextBlock status,hint;WpfButton copy,export,retry;
 public Action Copy,Export,Retry,OpenUrl;
 public ModernResultView(WF.Form owner,Mode mode,string language){this.mode=mode;Root=ModernChrome.Load("ModernResult");ModernChrome.WireFrame(Root,owner);((TextBlock)Root.FindName("WindowTitle")).Text=mode.ResultTitle+" · AI截图助手";((TextBlock)Root.FindName("ResultTitle")).Text=mode.ResultTitle;((TextBlock)Root.FindName("Description")).Text=mode.Index==1?"目标语言 · "+language:mode.Description;output=(WpfBox)Root.FindName("OutputText");table=(DataGrid)Root.FindName("OutputTable");status=(TextBlock)Root.FindName("Status");hint=(TextBlock)Root.FindName("Hint");copy=(WpfButton)Root.FindName("Copy");export=(WpfButton)Root.FindName("Export");retry=(WpfButton)Root.FindName("Retry");export.Content=mode.Index==4?"导出 TSV":"导出文本";copy.Click+=(s,e)=>{if(Copy!=null)Copy();};export.Click+=(s,e)=>{if(Export!=null)Export();};retry.Click+=(s,e)=>{if(Retry!=null)Retry();};((WpfButton)Root.FindName("OpenUrl")).Click+=(s,e)=>{if(OpenUrl!=null)OpenUrl();};if(mode.Index==5){output.Text="正在本地识别二维码…";status.Text="本地解码";hint.Text="无需网络与 API Key";}}
 public void EnableSmartSwitch(Action<int> change){var picker=(ComboBox)Root.FindName("SmartMode");foreach(var item in Mode.All)if(item.Index<6)picker.Items.Add(item.Title);picker.SelectedIndex=mode.Index;((FrameworkElement)Root.FindName("SmartBar")).Visibility=Visibility.Visible;((WpfButton)Root.FindName("ChangeMode")).IsEnabled=false;((WpfButton)Root.FindName("ChangeMode")).Click+=(s,e)=>{if(picker.SelectedIndex>=0&&picker.SelectedIndex!=mode.Index)change(picker.SelectedIndex);};((TextBlock)Root.FindName("Description")).Text="智能判断 · "+mode.Title+"，可切换处理方式";}
 public void Partial(string text){output.Text=text;status.Text="正在生成…";hint.Text="可先阅读，完成后可复制";}
 public void Success(string text){((WpfButton)Root.FindName("ChangeMode")).IsEnabled=true;output.Text=text;if(mode.Index==4&&text.Contains("\t")){var data=new DataTable();string[] lines=text.Replace("\r\n","\n").TrimEnd('\n').Split('\n');string[] headers=lines[0].Split('\t');for(int i=0;i<headers.Length&&i<64;i++)data.Columns.Add("c"+i,typeof(string));for(int i=1;i<lines.Length&&i<=1000;i++){string[] cells=lines[i].Split('\t');var row=data.NewRow();for(int c=0;c<data.Columns.Count;c++)row[c]=c<cells.Length?cells[c]:"";data.Rows.Add(row);}table.AutoGeneratingColumn+=(s,e)=>{int i=int.Parse(e.PropertyName.Substring(1));e.Column.Header=string.IsNullOrWhiteSpace(headers[i])?"列 "+(i+1):headers[i];};table.ItemsSource=data.DefaultView;table.Visibility=Visibility.Visible;output.Visibility=Visibility.Collapsed;}Uri uri;((WpfButton)Root.FindName("OpenUrl")).Visibility=mode.Index==5&&QrDecoder.WebUrl(text,out uri)?Visibility.Visible:Visibility.Collapsed;copy.IsEnabled=export.IsEnabled=true;retry.Content="重新框选";status.Text="已完成";hint.Text=mode.Index==4?"可直接复制到 Excel":"结果未自动覆盖剪贴板";}
 public void Failure(string error){((WpfButton)Root.FindName("ChangeMode")).IsEnabled=true;output.Text="暂时未能完成\r\n\r\n"+error;status.Text="生成失败";hint.Text="检查连接设置，或重新框选";retry.Content="重新框选";}
 public void Note(string text){if(!Root.Dispatcher.CheckAccess()){if(!Root.Dispatcher.HasShutdownStarted)Root.Dispatcher.BeginInvoke(new Action(()=>Note(text)));return;}status.Text=text;}
}

sealed class ResultEscapeFilter:WF.IMessageFilter,IDisposable {
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]static extern IntPtr GetAncestor(IntPtr handle,uint flags);
 WF.Form owner;bool installed;
 public ResultEscapeFilter(WF.Form form,UserControl root){owner=form;root.AddHandler(Keyboard.PreviewKeyDownEvent,new KeyEventHandler((s,e)=>{if(e.Key==Key.Escape){e.Handled=true;if(!owner.IsDisposed)owner.Close();}}),true);owner.Shown+=(s,e)=>{if(!installed){WF.Application.AddMessageFilter(this);installed=true;}};owner.FormClosed+=(s,e)=>Dispose();owner.Disposed+=(s,e)=>Dispose();}
 public bool PreFilterMessage(ref WF.Message message){if(owner.IsDisposed||(message.Msg!=0x100&&message.Msg!=0x104)||message.WParam.ToInt32()!=(int)WF.Keys.Escape)return false;IntPtr active=GetForegroundWindow();if(active!=owner.Handle&&GetAncestor(active,2)!=owner.Handle)return false;owner.Close();return true;}
 public void Dispose(){if(installed){WF.Application.RemoveMessageFilter(this);installed=false;}}
}
